export const $=id=>document.getElementById(id);
const icon=id=>`<svg><use href="#i-${id}"/></svg>`;
const portraits={};
export class UI{
 constructor(engine,world,callbacks){for(const h of HEROES)portraits[h.id]=portrait(h.id);this.e=engine;this.w=world;this.cb=callbacks;this.opened=null;this.studioFrame=0;this.bind();this.renderParty();}
 bind(){$('quick-skills').onclick=()=>this.skills();$('quest-toggle').onclick=()=>{const expanded=$('quest-toggle').getAttribute('aria-expanded')==='true';$('quest-toggle').setAttribute('aria-expanded',String(!expanded));$('quest-details').hidden=expanded;};$('minimap-btn').onclick=()=>this.map();$('journal-btn').onclick=()=>this.journal();$('quest-journal-btn').onclick=()=>this.journal();$('party-btn').onclick=()=>this.party();$('studio-btn').onclick=()=>this.studio();$('settings-btn').onclick=()=>this.settings();$('time-btn').onclick=()=>this.time();$('help-btn').onclick=()=>this.help();$('render-btn').onclick=()=>this.actions();$('emote-btn').onclick=()=>this.e.action('sit');$('interact-prompt').onclick=()=>this.e.action('interact');document.querySelectorAll('[data-action]').forEach(b=>{b.addEventListener('pointerdown',ev=>{ev.preventDefault();if(!this.opened){this.e.action(b.dataset.action);if(b.dataset.action==='interact'){b.setPointerCapture(ev.pointerId);this.attackHold=setInterval(()=>{if(!this.opened&&!this.e.primaryContext())this.e.action('attack');},120);}}});for(const event of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(event,()=>clearInterval(this.attackHold));});document.querySelector('.brand')?.addEventListener('click',ev=>{ev.preventDefault();this.help();});}
 toast(text,warn=false){const t=document.createElement('div');t.className='toast'+(warn?' warn':'');t.textContent=text;$('toasts').append(t);setTimeout(()=>t.remove(),2800);while($('toasts').children.length>(matchMedia('(pointer:coarse)').matches?1:2))$('toasts').firstChild.remove();}
 modal(title,eyebrow,sub,body,cls=''){this.close();this.opened=title;$('modal-root').innerHTML=`<div class="modal-shade"><section class="modal ${cls}" role="dialog" aria-modal="true" aria-label="${title}"><div class="modal-head"><div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p class="sub">${sub}</p></div><button class="close-btn" aria-label="Close menu">×</button></div>${body}</section></div>`;$('modal-root').querySelector('.close-btn').onclick=()=>this.close();$('modal-root').querySelector('.modal-shade').onclick=ev=>{if(ev.target.classList.contains('modal-shade'))this.close();};$('modal-root').querySelector('.close-btn').focus();}
 close(force=false){clearInterval(this.attackHold);if(this.opened==='title-screen'&&!force)return;this.opened=null;$('modal-root').innerHTML='';if(this.studioRaf)cancelAnimationFrame(this.studioRaf);this.studioRaf=null;this.cb.clearInput?.();}
 onboarding(){this.close(true);this.opened='title-screen';document.body.classList.add('on-title');$('modal-root').innerHTML=`<section class="intro minimal-intro" role="dialog" aria-modal="true" aria-label="Choose your adventure"><div class="title-stars" aria-hidden="true"></div><div class="title-menu"><img class="title-emblem" src="favicon.svg" alt=""><h1>JUJUTSU<br><em>VALLEY</em></h1><p class="title-caption">Choose your path.</p><div class="mode-panel"><button class="mode-choice sandbox" data-start-mode="sandbox"><span><b>SANDBOX</b><small>${this.cb.hasSave('sandbox')?'Continue exploring':'Explore freely'}</small></span><span class="mode-arrow">→</span></button><button class="mode-choice survival" data-start-mode="survival"><span><b>SURVIVAL</b><small>${this.cb.hasSave('survival')?'Continue your campaign':'Quests & boss hunts'}</small></span><span class="mode-arrow">→</span></button></div><p class="title-save-note">Two adventures. Separate saves.</p></div></section>`;document.querySelectorAll('[data-start-mode]').forEach(b=>b.onclick=()=>{const mode=b.dataset.startMode;this.close(true);document.body.classList.remove('on-title');this.cb.startMode(mode);if(!this.cb.tutorialSeen())this.tutorial(mode);else this.toast(mode==='survival'?'Your next objective is in the Quest Journal.':'Welcome back. The valley is yours.');});}
 tutorial(mode,step=0){const steps=[['Find your footing','Move with WASD or the arrow keys. On a phone, drag the left thumbstick. Shift, 4 or Dash gives a brief dodge. In Survival, dodging cancels your pending attack and has a 2.4-second cooldown.'],['Make the valley your home','Walk near a tree, crystal, crop, or checkpoint and use Interact. The minimap opens your world map; there is one map control.'],['Collect your sorcerers','One sorcerer fights at a time. Claim quest rewards to collect heroes, then deploy them from Collection outside combat. Techniques 1–3 arc upwards beside Attack; Dash is skill 4 at the top. Upgrade the skill tree to unlock signature effects.'],['Write your own story',mode==='survival'?'Open Quests or press J. Complete objectives, claim rewards, and start named boss hunts in their marked regions. Defeating Sukuna completes the campaign.':'Sandbox opens every region and hero. Use Settings to summon enemies, and the clock to jump between day and night.']];const [title,body]=steps[step];this.modal(title,`FIELD GUIDE · ${step+1} / 4`,'',`<div class="tutorial-step"><span class="tutorial-number">0${step+1}</span><p>${body}</p></div><div class="button-row"><button class="primary" id="tutorial-next">${step===3?'Enter the valley':'Next →'}</button><button class="secondary" id="tutorial-skip">Skip guide</button></div>`,'narrow');const finish=()=>{this.cb.finishTutorial();this.close();};$('tutorial-skip').onclick=finish;$('tutorial-next').onclick=()=>step===3?finish():this.tutorial(mode,step+1);}
 renderParty(){const s=this.e.s;$('roster-count').textContent=s.recruited.length+' / 6';$('party-cards').innerHTML=s.party.map((id,i)=>{const h=HEROES.find(h=>h.id===id),a=s.heroes[id];return `<button class="party-card ${s.controlled===id?'active':''}" data-hero="${id}" aria-label="Play as ${h.name}"><img class="portrait" src="${portraits[id]}" alt="${h.short}"><div class="party-info"><b><span class="hero-name">${h.name}</span><span class="hero-short">${h.short}</span></b><small>${s.controlled===id?'YOU · ':''}LV. ${a.level} · ${a.hp<=0?'DOWNED':h.title.toUpperCase()}</small><div class="bar"><i id="hp-${id}" style="width:${a.hp/a.maxHp*100}%"></i></div><div class="bar energy"><i id="ce-${id}" style="width:${a.ce/a.maxCe*100}%"></i></div></div><span class="hero-level" id="level-${id}">Lv.${a.level}</span><span class="party-key">${['Z','C','F'][i]}</span></button>`;}).join('');document.querySelectorAll('[data-hero]').forEach(b=>b.onclick=()=>this.e.switchHero(b.dataset.hero));const h=HEROES.find(h=>h.id===s.controlled);const compact={gojo:['Blue','Red','Hollow Purple'],yuji:['Divergent Fist','Lunge','Black Flash'],megumi:['Divine Dog','Nue','Shadow Garden'],nobara:['Nail Volley','Hairpin','Resonance'],yuta:['Rika Strike','Cursed Speech','Rika'],maki:['Sweep','Vault Slam','Barrage']};h.abilities.forEach((n,i)=>{$(`ability${i}-name`).textContent=compact[h.id][i];const b=document.querySelector(`[data-action="ability${i}"]`);b.title=n;b.setAttribute('aria-label',n);});for(const [action,slot]of [['interact','interact'],['dash','dash'],['ability0',0],['ability1',1],['ability2',2]]){const b=document.querySelector(`[data-action="${action}"]`);let image=b.querySelector('.skill-art');if(!image){image=document.createElement('img');image.className='skill-art';image.alt='';const old=b.querySelector('svg,.ability-symbol');old?.replaceWith(image);}image.src=skillIcon(h.id,slot);b.dataset.skill=typeof slot==='number'?SKILL_THEMES[h.id][slot]:slot;b.dataset.hero=h.id;b.classList.toggle('ultimate-slot',slot===2);}}
 update(){const s=this.e.s,p=this.e.player;for(const id of s.party){const h=s.heroes[id];if($(`level-${id}`))$(`level-${id}`).textContent='Lv.'+h.level;if($(`hp-${id}`))$(`hp-${id}`).style.width=`${h.hp/h.maxHp*100}%`;if($(`ce-${id}`))$(`ce-${id}`).style.width=`${h.ce/h.maxCe*100}%`;}for(let i=0;i<3;i++){const el=document.querySelector(`[data-action="ability${i}"] .cooldown`);el.style.display=p.cooldowns[i]>0?'flex':'none';el.textContent=p.cooldowns[i].toFixed(1);}document.querySelector('.awakening-meter').classList.toggle('ready',p.gauge>=100||p.awake>0);$('gauge-fill').style.width=`${s.mode==='sandbox'?100:p.gauge}%`;const hourLabel=formatGameHour(s.clock);if($('clock').textContent!==hourLabel)$('clock').textContent=hourLabel;$('day-label').textContent=`DAY ${String(s.day).padStart(2,'0')} · ${s.freeze?'PAUSED':this.e.night?'CURTAIN':'SUNNY'}`;$('day-icon').setAttribute('href',this.e.night?'#i-moon':'#i-sun');$('mode-badge').textContent=s.mode.toUpperCase();for(const key of ['wood','crystal','herb','gem'])$(`${key}-count`).textContent=s.inventory[key];const r=REGIONS.find(r=>r.id===s.region);$('region-name').textContent=r.name;$('region-sub').textContent=r.subtitle;const ctx=this.e.primaryContext();$('interaction').classList.toggle('hidden',!ctx||!!this.opened);if(ctx)$('interaction').querySelector('span').textContent=ctx.label;this.updateCombatControls(ctx);const q=this.quest();$('quest-title').textContent=q[0];$('quest-text').textContent=q[1];const qs=s.mode==='survival'?questSummary(s):null;$('quest-count').textContent=qs?(qs.ready?'READY TO CLAIM':`${qs.current||0} / ${qs.total||0} objectives · ${ensureQuests(s).claimed.length} / 10 quests`):`${s.discovered.length} / 9 checkpoints attuned`;$('quest-progress').style.width=`${(qs?qs.progress:s.discovered.length/9)*100}%`;$('quest-toggle').classList.toggle('quest-ready',!!qs?.ready);if(['World map','Location map'].includes(this.opened)&&$('region-preview'))this.drawRegionPreview();$('area-status').textContent=s.bossActive?'Domain sealed · read the openings':s.combatTimer>0?'Cursed presence · stay close':s.region==='school'?'Sanctuary · take a breath':'Exploring · follow your curiosity';const boss=s.enemies.find(e=>e.isBoss);$('boss-bar').classList.toggle('hidden',!boss);document.body.classList.toggle('boss-fight',!!boss);if(boss){$('boss-name').textContent=boss.name;$('boss-poise').style.width=(boss.broken>0?100:Math.min(100,(boss.poise||0)/boss.maxPoise*100))+'%';$('boss-break-status').textContent=s.mode==='survival'?(boss.broken>0?'BROKEN · +30% DAMAGE':'STAGGER '+Math.floor(boss.poise||0)+' / '+boss.maxPoise):'';document.querySelector('.boss-poise').hidden=s.mode!=='survival';$('boss-health').style.width=`${boss.hp/boss.maxHp*100}%`;$('boss-energy').style.width=`${boss.ce/boss.maxCe*100}%`;$('boss-vitals').textContent=`HP ${Math.ceil(boss.hp)} / ${boss.maxHp} · CE ${Math.floor(boss.ce)} / ${boss.maxCe}`;$('boss-phase').textContent=`SPECIAL GRADE · LV ${boss.level} · PHASE ${boss.enraged?2:1}`;}this.drawMinimap();}
 updateCombatControls(ctx){const p=this.e.player,s=this.e.s,b=document.querySelector('[data-action="interact"]');b.classList.toggle('is-interact',!!ctx);b.setAttribute('aria-label',ctx?ctx.label:'Basic attack');$('primary-action-name').textContent=ctx?'INTERACT':'ATTACK';const art=b.querySelector('.skill-art');if(art){art.hidden=!!ctx;}let glyph=b.querySelector('.context-glyph');if(!glyph){glyph=document.createElement('span');glyph.className='context-glyph';glyph.textContent='✦';b.prepend(glyph);}glyph.hidden=!ctx;const steps=p.comboWindow>0?p.comboStep||0:0;$('combo-indicator').textContent=[1,2,3].map(i=>i<=steps?'◆':'◇').join(' ');$('combo-indicator').hidden=!!ctx||s.mode!=='survival';const basicCd=b.querySelector('.cooldown');basicCd.style.display=!ctx&&p.attackCd>.1?'flex':'none';basicCd.textContent=p.attackCd.toFixed(1);const dash=document.querySelector('[data-action="dash"]'),cd=dash.querySelector('.cooldown');cd.style.display=p.dashCd>0?'flex':'none';cd.textContent=p.dashCd.toFixed(1);dash.classList.toggle('no-energy',p.ce<10);for(let i=0;i<3;i++){const node=document.querySelector(`[data-action="ability${i}"]`),g=technique(p,i);node.querySelector('.rank-pips').textContent='◆'.repeat(g.rank)+'◇'.repeat(3-g.rank);node.classList.toggle('no-energy',p.ce<Math.ceil([45,65,140][i]*g.cost*(p.id==='gojo'&&p.awake>0?.2:1)));}const points=skillPoints(p);$('available-points').textContent=points;$('quick-skills').classList.toggle('has-points',points>0);$('quick-skills').title=points+' skill points';$('player-vitals').textContent=`HP ${Math.ceil(p.hp)} / ${p.maxHp} · CE ${Math.floor(p.ce)}${p.shield>0?' · SHIELD '+Math.ceil(p.shield):''}`;}
 quest(){const s=this.e.s;if(s.mode==='survival'){const q=questSummary(s);return [q.title,q.description];}if(s.mode==='sandbox')return ['Explore the world',REGIONS.find(r=>r.id===s.region).objective+'. Open the map to explore.'];if(!s.unlocked.includes('tokyo'))return ['Prepare for the Curtain',`Gather 3 resources in the forest to open Tokyo. ${Math.min(s.harvests,3)} / 3 gathered.`];if(!s.unlocked.includes('shibuya'))return ['Behind the everyday',`Exorcise 3 curses in Tokyo. ${Math.min(s.regionKills.tokyo||0,3)} / 3 cleared.`];if(!s.unlocked.includes('domain'))return ['Beneath the crossing','Attune both Shibuya checkpoints to uncover the domain.'];return ['Beyond the curtain','Enter the cursed domain. Deploy your strongest sorcerer.'];}
 drawMinimap(){const canvas=$('minimap'),ctx=canvas.getContext('2d'),s=this.e.s,r=REGIONS.find(r=>r.id===s.region),pos=(x,z)=>[100+x*200/36,78+z*156/30];ctx.imageSmoothingEnabled=false;if(this.w.ground)ctx.drawImage(this.w.ground,0,0,200,156);else{ctx.fillStyle='#273b39';ctx.fillRect(0,0,200,156);}ctx.fillStyle='#182b2e55';ctx.fillRect(0,0,200,156);for(const b of regionBuildings(s.region)){const [x,y]=pos(b.x,b.z);ctx.fillStyle='#273b4c';ctx.fillRect(x-b.w*200/72,y-b.d*156/60,b.w*200/36,b.d*156/30);}for(const cp of CHECKPOINTS.filter(c=>c.region===s.region)){const [x,y]=pos(cp.x,cp.z);ctx.fillStyle=s.discovered.includes(cp.id)?'#83dfe7':'#a1a7b8';ctx.beginPath();ctx.arc(x,y,3.2,0,7);ctx.fill();ctx.strokeStyle='#14223b';ctx.lineWidth=1;ctx.stroke();}for(const [to,x,z]of r.exits){const [X,Y]=pos(x,z);ctx.fillStyle='#e2c99a';ctx.fillRect(X-2,Y-2,4,4);}mapArtifacts(ctx,s,pos);paintEnemyMarkers(ctx,s,pos);for(const id of s.party){const h=s.heroes[id],[x,y]=pos(h.x,h.z);ctx.fillStyle=id===s.controlled?'#fff1c8':'#a4b9e0';ctx.beginPath();ctx.arc(x,y,id===s.controlled?3.8:2.2,0,7);ctx.fill();if(id===s.controlled){ctx.strokeStyle='#18243a';ctx.lineWidth=1.5;ctx.stroke();}}}

 skills(){const h=this.e.player,def=HEROES.find(v=>v.id===h.id);this.modal('Skill tree',def.name.toUpperCase(),`Level ${h.level} · ${skillPoints(h)} skill points available. Earn one point per level.`, `<div class="skill-tree">${def.abilities.map((name,slot)=>{const g=technique(h,slot),next=g.rank+1;return `<article class="skill-branch"><div class="skill-branch-title"><img src="${skillIcon(h.id,slot)}" alt=""><div><h3>${name}</h3><p>${g.directions} directions · +${Math.round((g.damage-1)*100)}% damage · −${Math.round((1-g.cooldown)*100)}% cooldown</p></div></div><p class="mastery-effect">${g.rank?g.effect:'Base technique · upgrade for a signature effect'}</p><p class="mastery-next">${next<=3?'Next: '+technique({...h,skillRanks:[0,1,2].map(i=>i===slot?next:technique(h,i).rank)},slot).effect:'Full mastery'}</p><div class="skill-nodes">${DIRECTIONS.map((n,i)=>`<div class="skill-node ${i<=g.rank?'learned':''}"><span>${n}</span><small>${i===0?'BASE':'LV '+SKILL_LEVELS[i]}</small></div>`).join('')}</div><button class="primary" data-upgrade="${slot}" ${next>3||h.level<SKILL_LEVELS[next]||skillPoints(h)<1?'disabled':''}>${next>3?'Mastered · 10 directions':`Upgrade · 1 point · requires Lv.${SKILL_LEVELS[next]}`}</button></article>`;}).join('')}</div><p class="studio-note">Your signature technique releases a ring of cursed-energy echoes. Each enemy can take one echo hit per cast. Every rank adds 25% damage, reduces cooldown 8% and energy cost 6%, adds range and break pressure. Signature effects shown above apply in Survival. Stagger breaks interrupt attacks and open a 30% damage window. Every hero has their own three branches.</p>`);document.querySelectorAll('[data-upgrade]').forEach(b=>b.onclick=()=>{this.e.upgrade(Number(b.dataset.upgrade));this.skills();});}
 localMap(region=this.e.s.region){const s=this.e.s,r=REGIONS.find(r=>r.id===region);this.modal('Location map',r.name.toUpperCase(),'Explore, collect relics, and attune checkpoints.',`<div class="map-tabs"><button class="primary" id="local-tab">Location</button><button class="secondary" id="world-tab">World</button></div><div class="local-map-layout"><div class="region-preview local-preview"><canvas id="region-preview" data-region="${region}" width="360" height="240"></canvas></div><div class="map-key"><span>◆ Gold: artifact</span><span>■ Cyan: checkpoint</span><span>◇ Sand: exit</span><span>● Red: curse / outlined: boss</span><span>■ White: player</span><span>■ Grey: recovered</span></div><div class="location-index"><h3>Checkpoints</h3>${CHECKPOINTS.filter(c=>c.region===region).map(c=>`<div class="checkpoint"><div><b>${c.name}</b><small>${s.discovered.includes(c.id)?'Attuned':'Not attuned'}</small></div><button class="secondary small" data-local-travel="${c.id}" ${!s.discovered.includes(c.id)||!s.unlocked.includes(region)||!travelAllowed(s)?'disabled':''}>Teleport</button></div>`).join('')}<h3>Artifacts · ${ARTIFACTS.filter(a=>a.region===region&&collected(s,a.id)).length} / 3</h3>${ARTIFACTS.filter(a=>a.region===region).map((a,i)=>`<div class="artifact-entry"><b>${i+1}. ${a.name}</b><span>${collected(s,a.id)?'Recovered':`+${a.gems} gems · ${a.xp} XP`}</span></div>`).join('')}<h3>Routes</h3>${r.exits.map(([id])=>`<button class="secondary small" data-local-region="${id}">${REGIONS.find(r=>r.id===id).name} →</button>`).join('')}</div></div>`);$('world-tab').onclick=()=>this.map(region);$('local-tab').onclick=()=>this.localMap(region);document.querySelectorAll('[data-local-region]').forEach(b=>b.onclick=()=>this.localMap(b.dataset.localRegion));document.querySelectorAll('[data-local-travel]').forEach(b=>b.onclick=()=>{this.close();this.e.travel(region,b.dataset.localTravel);});this.drawRegionPreview();}
 map(selected=this.e.s.region){const s=this.e.s,r=REGIONS.find(r=>r.id===selected),cp=CHECKPOINTS.filter(c=>c.region===selected);this.modal('World map','CHECKPOINT NETWORK','Choose an attuned checkpoint. Travel with your active sorcerer.',`<div class="map-tabs"><button class="secondary" id="local-tab">Location</button><button class="primary" id="world-tab">World</button></div><div class="map-layout"><div class="world-map"><canvas id="world-map-canvas" width="600" height="500"></canvas>${REGIONS.map((r,i)=>`<button class="region-node ${r.id===selected?'active':''} ${s.unlocked.includes(r.id)?'':'locked'}" data-region="${r.id}" style="left:${[24,70,30,69,45][i]}%;top:${[20,24,51,57,83][i]}%"><b>${r.name.replace('Tokyo ','').replace(' · The Curtain','')}</b><small>${s.region===r.id?'YOU ARE HERE'+(s.enemies.length?' · '+s.enemies.length+' CURSES':''):!s.unlocked.includes(r.id)?'UNDISCOVERED ROUTE':CHECKPOINTS.filter(c=>c.region===r.id&&s.discovered.includes(c.id)).length+' CHECKPOINTS · '+ARTIFACTS.filter(a=>a.region===r.id&&collected(s,a.id)).length+'/3 RELICS'}</small></button>`).join('')}</div><div class="checkpoint-list"><span class="eyebrow">${s.unlocked.includes(selected)?'OPEN REGION':'LOCKED REGION'}</span><h3>${r.name}</h3><p class="sub">${r.subtitle}</p><div class="region-preview"><canvas id="region-preview" data-region="${selected}" width="360" height="240"></canvas><span><i class="enemy-dot"></i> Curse <i class="boss-dot"></i> Boss <i class="ally-dot"></i> Player</span></div>${cp.map(c=>`<div class="checkpoint"><div><b>${icon('pin')} ${c.name}</b><small>${s.discovered.includes(c.id)?'Attuned · free teleport':'Visit this marker to attune'}</small></div><button class="secondary small" data-teleport="${c.id}" ${!s.discovered.includes(c.id)||!s.unlocked.includes(selected)||!travelAllowed(s)?'disabled':''}>Teleport ↗</button></div>`).join('')}<p class="studio-note">${!travelAllowed(s)?s.bossActive?'The boss has sealed this domain. Defeat it to travel.':'Travel returns 8 seconds after the last hostile hit.':'Your whole party travels together. Rest at a checkpoint to recover.'}</p><div class="map-legend"><span>◉ Attuned</span><span>◇ Region exit</span><span>● Your party</span></div></div></div>`);$('local-tab').onclick=()=>this.localMap(selected);$('world-tab').onclick=()=>this.map(selected);document.querySelectorAll('button[data-region]').forEach(b=>b.onclick=()=>this.map(b.dataset.region));document.querySelectorAll('[data-teleport]').forEach(b=>b.onclick=()=>{const c=CHECKPOINTS.find(c=>c.id===b.dataset.teleport);this.close();this.e.travel(c.region,c.id);});this.drawRegionPreview();const c=$('world-map-canvas').getContext('2d');c.fillStyle='#1c2940';c.fillRect(0,0,600,500);for(let i=0;i<80;i++){c.fillStyle=['#253752','#2c3e58','#33435c'][i%3];c.beginPath();c.arc((i*97)%600,(i*71)%500,10+i%8,0,7);c.fill();}c.strokeStyle='#6687ac';c.lineWidth=8;c.setLineDash([5,7]);for(const [a,b]of [[0,1],[0,2],[1,2],[2,3],[3,4]]){const x=[24,70,30,69,45],y=[20,24,51,57,83];c.beginPath();c.moveTo(x[a]*6,y[a]*5);c.lineTo(x[b]*6,y[b]*5);c.stroke();}}
 drawRegionPreview(){const el=$('region-preview');if(!el)return;const c=el.getContext('2d'),s=this.e.s,region=el.dataset.region,pos=(x,z)=>[180+x*10,120+z*8];c.imageSmoothingEnabled=false;if(region===s.region&&this.w.ground)c.drawImage(this.w.ground,0,0,360,240);else{c.fillStyle='#263b4b';c.fillRect(0,0,360,240);c.fillStyle='#667479';c.fillRect(167,0,26,240);c.fillRect(0,133,360,20);}if(region!==s.region)for(const pond of regionPonds(region)){const [x,y]=pos(pond.x,pond.z);c.fillStyle='#77b8c2';c.fillRect(x-pond.rx*10,y-pond.rz*8,pond.rx*20,pond.rz*16);}for(const b of regionBuildings(region)){const [x,y]=pos(b.x,b.z);c.fillStyle='#243749';c.fillRect(x-b.w*5,y-b.d*4,b.w*10,b.d*8);}for(const cp of CHECKPOINTS.filter(c=>c.region===region)){const [x,y]=pos(cp.x,cp.z);c.fillStyle=s.discovered.includes(cp.id)?'#7ae1df':'#7c90a7';c.fillRect(x-3,y-3,6,6);}mapArtifacts(c,s,pos,region);for(const [id,x,z]of REGIONS.find(r=>r.id===region).exits){const [X,Y]=pos(x,z);c.fillStyle='#e2c99a';c.fillRect(X-3,Y-3,6,6);}for(const [i,a]of ARTIFACTS.filter(a=>a.region===region).entries()){const [x,y]=pos(a.x,a.z);c.fillStyle='#fff0c5';c.font='10px monospace';c.fillText(String(i+1),x+5,y-3);}paintEnemyMarkers(c,s,pos,region);if(region===s.region)for(const id of s.party){const h=s.heroes[id],[x,y]=pos(h.x,h.z);c.fillStyle=id===s.controlled?'#fff0bb':'#b5d3fa';c.fillRect(x-2,y-2,5,5);} }
 journal(){const s=this.e.s,state=ensureQuests(s);if(s.mode==='sandbox'){this.modal('Quest journal','SANDBOX FIELD NOTES','Survival contains a ten-quest campaign and five named boss hunts. Sandbox keeps every region and sorcerer available.',`<div class="journal-empty"><h3>Your world. Your rules.</h3><p>Use the map to explore, summon curses from Settings, or choose Survival on the title screen to begin the campaign.</p><button class="primary" id="journal-survival">Enter Survival</button></div>`,'narrow');$('journal-survival').onclick=()=>{this.close();this.cb.changeMode('survival');this.journal();};return;}
 this.modal('Quest journal','SURVIVAL CAMPAIGN',`${state.claimed.length} / ${QUESTS.length} quests complete · rewards are claimed once.`,`${QUESTS.map(q=>{const claimed=state.claimed.includes(q.id),available=questAvailable(s,q),ready=questReady(s,q);return `<article class="quest-entry ${claimed?'claimed':available?'available':'locked'}"><div class="quest-entry-head"><span class="eyebrow">CHAPTER ${q.chapter} ${q.boss?'· BOSS HUNT':''}</span><span class="quest-state">${claimed?'COMPLETE':!available?'LOCKED':ready?'READY TO CLAIM':state.tracked===q.id?'TRACKED':'AVAILABLE'}</span></div><h3>${q.title}</h3>${q.boss?`<img class="quest-boss-portrait" src="art/characters/${q.boss}-south.png" alt="${ENEMIES.find(e=>e.id===q.boss).name}">`:``}<p>${q.description}</p><ul>${q.objectives.map(o=>`<li><span>${objectiveValue(s,o)>=o.target?'◆':'◇'} ${o.label}</span><b>${Math.min(objectiveValue(s,o),o.target)} / ${o.target}</b></li>`).join('')}</ul><div class="quest-rewards">${Object.entries(q.rewards).map(([k,n])=>`+${n} ${k}`).join(' · ')}${q.levelReward?' · +'+q.levelReward+' level':''}</div><div class="button-row">${claimed?'':ready?`<button class="primary" data-claim="${q.id}">Claim rewards</button>`:available?`<button class="secondary small" data-track="${q.id}">${state.tracked===q.id?'Tracking':'Track quest'}</button>${q.boss?`<button class="primary small" data-hunt="${q.id}" ${s.region!==q.region||!travelAllowed(s)?'disabled':''}>Start ${ENEMIES.find(e=>e.id===q.boss).name} hunt</button><span class="hunt-region">${REGIONS.find(r=>r.id===q.region).name}</span>`:''}`:''}</div></article>`;}).join('')}`);
 document.querySelectorAll('[data-claim]').forEach(b=>b.onclick=()=>{this.e.claim(b.dataset.claim);this.journal();});document.querySelectorAll('[data-track]').forEach(b=>b.onclick=()=>{this.e.trackQuest(b.dataset.track);this.journal();});document.querySelectorAll('[data-hunt]').forEach(b=>b.onclick=()=>{if(this.e.startHunt(b.dataset.hunt))this.close();}); }
 party(){const s=this.e.s;this.modal('Sorcerer collection','COLLECT · DEPLOY · MASTER',`${s.recruited.length} / 6 collected. One active sorcerer. Each keeps their own level, health, cursed energy and skill tree.`, `<div class="party-grid">${HEROES.map(h=>{const owned=s.recruited.includes(h.id),rule=COLLECTION.find(c=>c.id===h.id),a=s.heroes[h.id];return `<article class="hero-choice ${s.controlled===h.id?'active':''} ${owned?'':'uncollected'}"><span class="slot-label">${s.controlled===h.id?'DEPLOYED':owned?'COLLECTED':'SEALED'}</span><img src="${portraits[h.id]}" alt="${h.name}"><h3>${h.name}</h3><p>${h.title}</p><p>${owned?'Level '+a.level+' · '+Math.ceil(a.hp)+' / '+a.maxHp+' HP':rule?.hint||'Starting sorcerer'}</p><button class="${owned?'primary':'secondary'} small" data-play="${h.id}" ${!owned||s.controlled===h.id||s.combatTimer>0||s.bossActive||a.hp<=0?'disabled':''}>${s.controlled===h.id?'Currently playing':owned?'Deploy '+h.short:'Collect through quests'}</button></article>`;}).join('')}</div><p class="studio-note">Change sorcerers outside combat. Inactive characters remain in your collection and do not follow or fight. Previously collected heroes are preserved. Sandbox includes the full roster.</p>`);document.querySelectorAll('[data-play]').forEach(b=>b.onclick=()=>{if(this.e.switchHero(b.dataset.play))this.party();});}
 actions(){const gojo=this.e.player.id==='gojo';this.modal('Character actions','FIELD COMMANDS','Quick commands for your active sorcerer.',`<div class="command-grid"><button class="command" data-command="special">${icon('eye')}<span><b>${HEROES.find(h=>h.id===this.e.player.id).special}</b><small>Signature awakening · R · ${Math.ceil(this.e.player.specialCd)}s cooldown</small></span></button><button class="command" data-command="gear">${icon('eye')}<span><b>${gojo?'Change headgear':'Wave'}</b><small>${gojo?'Blindfold / sunglasses':'Greet the courtyard'}</small></span></button><button class="command" data-command="infinity" ${gojo?'':'disabled'}>${icon('domain')}<span><b>Infinity</b><small>${gojo?(this.e.player.infinity?'Active · tap to release':'Toggle Gojo’s barrier'):'Available when playing Gojo'}</small></span></button><button class="command" data-command="sit">${icon('mochi')}<span><b>Sit & recover</b><small>Rest and snack on mochi</small></span></button><button class="command" id="command-skills">${icon('domain')}<span><b>Skill tree</b><small>${skillPoints(this.e.player)} points · evolve your techniques</small></span></button><button class="command" id="command-studio">${icon('grid')}<span><b>Sprite studio</b><small>Inspect & export the character bible</small></span></button><button class="command" id="command-settings">${icon('gear')}<span><b>Game settings</b><small>Sound, cut-ins & game mode</small></span></button></div>`,'narrow');document.querySelectorAll('[data-command]').forEach(b=>b.onclick=()=>{const action=b.dataset.command;this.close();this.e.action(action);});$('command-skills').onclick=()=>this.skills();$('command-studio').onclick=()=>this.studio();$('command-settings').onclick=()=>this.settings();}
 time(){this.modal('World clock','DAY & NIGHT','Time runs continuously; the HUD updates on the hour. The Curtain falls at 18:00.',`<div class="setting-row"><div><b>The passing of time</b><small>${this.e.s.freeze?'Paused at this moment':'The world is moving'}</small></div><button id="freeze-time" class="secondary">${this.e.s.freeze?'Resume time':'Pause time'}</button></div><div class="button-row"><button class="primary" id="jump-day">☀ Sunny day · 08:00</button><button class="secondary" id="jump-night">☾ Cursed night · 20:00</button></div><p class="studio-note">Manual time controls are available in Sandbox. Survival follows its natural cycle.</p>`,'narrow');$('freeze-time').disabled=this.e.s.mode!=='sandbox';$('jump-day').disabled=$('jump-night').disabled=this.e.s.mode!=='sandbox';$('freeze-time').onclick=()=>{this.e.s.freeze=!this.e.s.freeze;this.time();};$('jump-day').onclick=()=>{this.e.s.clock=8;this.close();this.toast('A fresh little morning.');};$('jump-night').onclick=()=>{this.e.s.clock=20;this.close();this.toast('The Curtain falls.');};}
 settings(){this.modal('Game settings','FIELD OPTIONS','Progress saves automatically on this browser. Sandbox and Survival keep separate saves.',`<div class="setting-row"><div><b>Game mode</b><small>Sandbox is open exploration. Survival earns its progress.</small></div><select id="mode-select"><option value="sandbox">Sandbox</option><option value="survival">Survival</option></select></div><div class="setting-row"><div><b>Ultimate cut-ins</b><small>Layered 2.5D cinematics. Characters and the world stay 2D.</small></div><select id="render-select"><option value="on">On</option><option value="off">Off</option></select></div><div class="setting-row"><div><b>Sound effects</b><small>Soft, synthesized cues. Starts after your first gesture.</small></div><button id="sound-toggle" class="secondary small">${this.cb.soundEnabled()?'On':'Off'}</button></div><div class="setting-row"><div><b>Field notes</b><small>Controls, world rules, and party tips.</small></div><button id="open-help" class="secondary small">How to play</button></div><div class="button-row"><button id="title-btn" class="secondary">Title screen</button><button id="save-now" class="primary">Save adventure</button><button id="download-save" class="secondary">Export save</button><button id="spawn-curse" class="secondary" ${this.e.s.mode!=='sandbox'?'disabled':''}>Summon a curse</button><button id="spawn-boss" class="secondary" ${this.e.s.mode!=='sandbox'?'disabled':''}>Summon boss</button></div>`,'narrow');$('mode-select').value=this.e.s.mode;$('render-select').value=this.cb.cinematicsEnabled()?'on':'off';$('mode-select').onchange=ev=>{this.close();this.cb.changeMode(ev.target.value);};$('render-select').onchange=ev=>{if((ev.target.value==='on')!==this.cb.cinematicsEnabled())this.cb.toggleCinematics();};$('sound-toggle').onclick=ev=>{this.cb.toggleSound();ev.target.textContent=this.cb.soundEnabled()?'On':'Off';};$('open-help').onclick=()=>this.help();$('title-btn').onclick=()=>{this.cb.save();this.onboarding();};$('save-now').onclick=()=>{this.cb.save();this.toast('Adventure saved.');};$('download-save').onclick=()=>this.download(JSON.stringify(this.cb.saveData(),null,2),'chibi-world-save.json','application/json');$('spawn-curse').onclick=()=>{this.e.spawn('lurker',this.e.player.x+4,this.e.player.z-3);this.close();};$('spawn-boss').onclick=()=>{this.e.spawnBoss();this.close();};}
 help(){this.modal('Field guide','WELCOME TO JUJUTSU VALLEY','Gather by day. Read the danger by night. There is always time for a snack.',`<div class="help-grid"><div><kbd>WASD / ↑↓←→</kbd> Move · mobile: left stick</div><div><kbd>E / Space</kbd> Context action or melee</div><div><kbd>1 · 2 · 3</kbd> Techniques and ultimate</div><div><kbd>Shift</kbd> Dodge · 0.26s protection in Survival</div><div><kbd>R</kbd> Special / Gojo awakening</div><div><kbd>Q</kbd> Gojo’s Infinity barrier</div><div><kbd>Z · C · F</kbd> Deploy collected sorcerer (outside combat)</div><div><kbd>X</kbd> Sit, snack, and regenerate</div><div><kbd>V</kbd> Gojo headgear / hero wave</div><div><kbd>M · P · B</kbd> Map · collection · sprite studio</div></div><p class="studio-note">Walk up to resources and use Interact. Water crops three times, then harvest. Upgrade lanterns with wood and crystals to heal allies and slow curses. Touch a checkpoint to discover it; use the world map to teleport outside combat. One sorcerer fights at a time. Collect more through Survival quests. Hold Attack to chain three basics, dodge directional telegraphs and build stagger to break enemies. Survival stops passive health recovery in combat and slows cursed-energy regeneration; basics restore energy. Skill upgrades reduce cooldown and energy cost and add signature effects. On mobile, techniques aim toward a nearby visible enemy.</p><div class="button-row"><button id="guide-close" class="primary">Let's wander ↗</button></div>`,'narrow');$('guide-close').onclick=()=>this.close();}
 download(data,name,type){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 studio(){this.modal('Animation studio','SPRITE MAP BIBLE','Inspect the new full-body drawings used in gameplay. Movement, combat, casts and interactions each select their own drawn poses.',`<div class="studio-layout"><div class="studio-controls"><div><label for="studio-hero">CHARACTER</label><select id="studio-hero">${HEROES.map(h=>`<option value="${h.id}">${h.name}</option>`).join('')}${ENEMIES.map(e=>`<option value="enemy:${e.id}">${e.name} · curse</option>`).join('')}</select></div><div><label for="studio-clip">ANIMATION</label><select id="studio-clip">${CLIPS.map((c,i)=>`<option value="${i}">${String(i+1).padStart(2,'0')} · ${c.id.replaceAll('_',' ')}</option>`).join('')}</select></div><div><label for="studio-gear">HEADGEAR</label><select id="studio-gear"><option value="blindfold">Blindfold</option><option value="sunglasses">Round sunglasses</option><option value="eyes">Unsealed Six Eyes</option></select></div><div><label for="studio-direction">DIRECTION</label><select id="studio-direction"><option value="south">South · front</option><option value="north">North · back</option><option value="side">East · side</option><option value="west">West · mirrored</option></select></div><label class="studio-check"><input id="studio-debug" type="checkbox" checked> Anchors & hitboxes</label><label class="studio-check"><input id="studio-extra" type="checkbox"> Supplemental sheet</label><div class="button-row"><button class="primary small" id="export-png">Export PNG ↗</button><button class="secondary small" id="export-json">Export JSON ↗</button><button class="secondary small" id="export-bible">Full bible JSON ↗</button><a href="animation-library.html" target="_blank" class="text-btn">Inspect newly drawn animations ↗</a><a href="sprite-bible.md" download class="text-btn">Read the written bible ↗</a><a href="atlases/manifest.json" download class="text-btn">Prebaked asset index ↗</a><a href="skill-atlas.png" download class="text-btn">Skill icon atlas ↗</a><a href="art/model-sheets/heroes.webp" download class="text-btn">Hero model sheet ↗</a><a href="art/model-sheets/curses-companions.webp" download class="text-btn">Curse model sheet ↗</a></div></div><div><div class="studio-stage"><canvas id="studio-canvas" width="512" height="512"></canvas><div class="studio-transport"><button id="studio-play" aria-label="Pause animation">Ⅱ</button><input aria-label="Animation frame" id="studio-scrub" type="range" min="0" max="5" value="0"></div><p class="studio-note" id="studio-caption">Frame 1 / 6 · 8 FPS</p></div><div class="atlas-strip"><canvas id="atlas-canvas"></canvas></div><p class="studio-note">Tap any populated cell in the sheet to inspect that frame.</p></div><aside class="studio-data"><h3>Calculated frame</h3><dl id="studio-values"></dl></aside></div>`,'wide');let playing=true,last=performance.now(),acc=0;const get=()=>({hero:$('studio-hero').value,clip:Number($('studio-clip').value),gear:$('studio-gear').value,direction:$('studio-direction').value,extra:$('studio-extra').checked});const isEnemy=()=>get().hero.startsWith('enemy:');
 const enemyClip=(i)=>['idle','walk','telegraph','attack','hurt','defeat','recovery'][i%7];
 const drawEnemyFrame=(ctx,id,clip,frame)=>drawEnemyAnimation(ctx,ENEMIES.find(e=>e.id===id),enemyClip(clip),frame);
 const enemyAtlas=()=>{const st=get(),c=document.createElement('canvas');c.width=1024;c.height=896;const ctx=c.getContext('2d');for(let r=0;r<7;r++)for(let f=0;f<8;f++){ctx.save();ctx.translate(f*128,r*128);drawEnemyFrame(ctx,st.hero.split(':')[1],r,f);ctx.restore();}return c;};
 const rebuild=()=>{const st=get(),target=$('atlas-canvas'),atlas=isEnemy()?enemyAtlas():createAtlas(st.hero,st.gear,st.direction,st.extra);target.width=atlas.width;target.height=atlas.height;target.getContext('2d').drawImage(atlas,0,0);};
 const render=()=>{if(!this.opened||!$('studio-canvas'))return;const st=get(),clip=CLIPS[st.clip],frames=isEnemy()?8:clip.frames;this.studioFrame%=frames;const c=$('studio-canvas').getContext('2d');c.setTransform(4,0,0,4,0,0);c.clearRect(0,0,128,128);if(isEnemy())drawEnemyFrame(c,st.hero.split(':')[1],st.clip,this.studioFrame);else drawHero(c,st.hero,st.clip,this.studioFrame,st.direction,st.gear,$('studio-debug').checked);$('studio-scrub').max=frames-1;$('studio-scrub').value=this.studioFrame;$('studio-caption').textContent=`${isEnemy()?enemyClip(st.clip):clip.id} · Frame ${this.studioFrame+1} / ${frames} · ${isEnemy()?12:clip.fps} FPS`;const m=frameMetadata(st.clip,this.studioFrame,st.direction,st.gear);$('studio-values').innerHTML=`<div><dt>CELL</dt><dd>128 × 128 px</dd></div><div><dt>GROUND ANCHOR</dt><dd>(64, 116)</dd></div><div><dt>NEUTRAL BODY</dt><dd>156 source pixels</dd></div><div><dt>BODY COLLISION</dt><dd>Fixed ground circle · 0.45 world units</dd></div><div><dt>WEAPON SPACE</dt><dd>Separate 512px drawing viewport</dd></div><div><dt>FRAME DURATION</dt><dd>${(1000*(isEnemy()?1/12:frameDurations(clip)[this.studioFrame%clip.frames])).toFixed(2)} ms</dd></div><div><dt>EVENT</dt><dd>${isEnemy()?enemyClip(st.clip):m.event||'—'}</dd></div>`;};
 for(const id of ['studio-hero','studio-gear','studio-direction','studio-extra'])$(id).onchange=()=>{this.studioFrame=0;if(id==='studio-hero'){const enemy=isEnemy();$('studio-gear').disabled=enemy;$('studio-direction').disabled=enemy;Array.from($('studio-clip').options).forEach((o,i)=>{o.hidden=enemy&&i>=7;o.textContent=enemy?enemyClip(i).toUpperCase():`${String(i+1).padStart(2,'0')} · ${CLIPS[i].id.replaceAll('_',' ')}`;});$('studio-clip').value=0;}rebuild();render();};$('studio-clip').onchange=()=>{this.studioFrame=0;render();};$('studio-debug').onchange=render;$('studio-scrub').oninput=ev=>{playing=false;$('studio-play').textContent='▶';this.studioFrame=Number(ev.target.value);render();};$('studio-play').onclick=()=>{playing=!playing;$('studio-play').textContent=playing?'Ⅱ':'▶';};$('atlas-canvas').onclick=ev=>{const st=get(),rect=ev.target.getBoundingClientRect(),x=(ev.clientX-rect.left)/rect.width*ev.target.width,y=(ev.clientY-rect.top)/rect.height*ev.target.height;const row=Math.floor(y/128)+(st.extra&&!isEnemy()?18:0),f=Math.floor(x/128);if(row<(isEnemy()?7:24)&&f<(isEnemy()?8:CLIPS[row].frames)){$('studio-clip').value=row;this.studioFrame=f;playing=false;$('studio-play').textContent='▶';render();}};
 $('export-png').onclick=()=>{const st=get(),atlas=isEnemy()?enemyAtlas():createAtlas(st.hero,st.gear,st.direction,st.extra);atlas.toBlob(b=>{const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=`${st.hero.replace(':','-')}-${st.gear}-${st.direction}${st.extra?'-extra':''}.png`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);});};
 $('export-json').onclick=()=>{const st=get(),data=isEnemy()?{hero:st.hero,cell:{w:128,h:128},anchor:{x:64,y:116},animations:Array.from({length:7},(_,i)=>({id:enemyClip(i),frames:8,fps:12,active:i===3?[3]:[],duration:8/12}))}:atlasMetadata(st.hero,st.gear,st.direction,st.extra);this.download(JSON.stringify(data,null,2),`${st.hero.replace(':','-')}-atlas.json`,'application/json');};
 $('export-bible').onclick=()=>{const data={version:3,motionProfiles:MOTION,progression:{directions:DIRECTIONS,requiredLevels:SKILL_LEVELS,pointsPerLevel:1,damagePerRank:.25,costPerRank:-.06,cooldownPerRank:-.08,echoHitsPerTargetPerCast:1},artifacts:ARTIFACTS,style:'poster-chibi-pixel',nativeGrid:128,characterArt:'art/characters/manifest.json',reference:'art/battle-poster.webp',skillAtlas:'skill-atlas.json',quests:QUESTS,heroes:HEROES,clips:CLIPS,enemies:ENEMIES,regions:REGIONS,checkpoints:CHECKPOINTS,atlas:{cell:128,columns:8,rows:18,width:1024,height:2304,anchor:{x:64,y:116}},equations:{frameDuration:'1 / FPS',clipDuration:'frames / FPS',walkBounce:'-3 * abs(sin(PI * frame / 4))',hairLag:'2 * sin(phase * 2PI - PI/4)',infinity:'clamp(((distance - 0.65)/0.95)^3, 0, 1)',bluePull:'18 / max(0.5, distance)^1.2',sixEyes:{cost:.2,damage:1.5,cooldown:.5}},frames:HEROES.map(h=>({hero:h.id,animations:CLIPS.map(c=>({id:c.id,frames:Array.from({length:c.frames},(_,f)=>frameMetadata(c.row,f,'south','blindfold'))}))}))};this.download(JSON.stringify(data,null,2),'chibi-world-complete-sprite-bible.json','application/json');};
 rebuild();render();const tick=now=>{if(!this.opened||!$('studio-canvas'))return;const dt=(now-last)/1000;last=now;if(playing){acc+=dt;const clip=CLIPS[get().clip],duration=isEnemy()?1/12:frameDurations(clip)[this.studioFrame%clip.frames];if(acc>=duration){this.studioFrame++;acc-=duration;render();}}this.studioRaf=requestAnimationFrame(tick);};this.studioRaf=requestAnimationFrame(tick);}
}
